import{f as e,c as r,o as t,ah as i}from"./chunks/framework.5bt9HFMa.js";const c=JSON.parse('{"title":"第二章 软件设计原则（SOLID + 其他）","description":"详细介绍SOLID原则及其他软件设计原则，包括SRP、OCP、LSP、ISP、DIP等。","frontmatter":{"title":"第二章 软件设计原则（SOLID + 其他）","date":"2025-11-19T00:00:00.000Z","description":"详细介绍SOLID原则及其他软件设计原则，包括SRP、OCP、LSP、ISP、DIP等。"},"headers":[],"relativePath":"series/软件设计体系结构/02-软件设计原则.md","filePath":"series/软件设计体系结构/02-软件设计原则.md","lastUpdated":1763653616000}'),o={name:"series/软件设计体系结构/02-软件设计原则.md"};function l(s,a,h,n,d,_){return t(),r("div",null,a[0]||(a[0]=[i('<h1 id="第二章-软件设计原则-solid-其他" tabindex="-1">第二章 软件设计原则（SOLID + 其他） <a class="header-anchor" href="#第二章-软件设计原则-solid-其他" aria-label="Permalink to &quot;第二章 软件设计原则（SOLID + 其他）&quot;">​</a></h1><h2 id="_2-1-单一职责原则-srp" tabindex="-1">2.1 单一职责原则（SRP） <a class="header-anchor" href="#_2-1-单一职责原则-srp" aria-label="Permalink to &quot;2.1 单一职责原则（SRP）&quot;">​</a></h2><p>一个类应该只有一个改变的理由，即一个类只应该负责一个功能。</p><h2 id="_2-2-开闭原则-ocp" tabindex="-1">2.2 开闭原则（OCP） <a class="header-anchor" href="#_2-2-开闭原则-ocp" aria-label="Permalink to &quot;2.2 开闭原则（OCP）&quot;">​</a></h2><p>软件实体（类、模块、函数等）应该对扩展开放，对修改关闭。</p><h2 id="_2-3-里氏替换原则-lsp" tabindex="-1">2.3 里氏替换原则（LSP） <a class="header-anchor" href="#_2-3-里氏替换原则-lsp" aria-label="Permalink to &quot;2.3 里氏替换原则（LSP）&quot;">​</a></h2><p>子类对象能够替换其父类对象，而不会破坏程序的正确性。</p><h2 id="_2-4-接口隔离原则-isp" tabindex="-1">2.4 接口隔离原则（ISP） <a class="header-anchor" href="#_2-4-接口隔离原则-isp" aria-label="Permalink to &quot;2.4 接口隔离原则（ISP）&quot;">​</a></h2><p>客户端不应该被迫依赖其不使用的接口，应该将大接口分解为更小的、特定的接口。</p><h2 id="_2-5-依赖倒置原则-dip" tabindex="-1">2.5 依赖倒置原则（DIP） <a class="header-anchor" href="#_2-5-依赖倒置原则-dip" aria-label="Permalink to &quot;2.5 依赖倒置原则（DIP）&quot;">​</a></h2><p>高层模块不应该依赖低层模块，两者都应该依赖于抽象。此外，抽象不应该依赖于具体，具体应该依赖于抽象。</p><h2 id="_2-6-迪米特法则-最少知识原则" tabindex="-1">2.6 迪米特法则（最少知识原则） <a class="header-anchor" href="#_2-6-迪米特法则-最少知识原则" aria-label="Permalink to &quot;2.6 迪米特法则（最少知识原则）&quot;">​</a></h2><p>一个对象应该只与其直接的朋友交互，避免与陌生人交互。</p><h2 id="_2-7-高内聚低耦合" tabindex="-1">2.7 高内聚低耦合 <a class="header-anchor" href="#_2-7-高内聚低耦合" aria-label="Permalink to &quot;2.7 高内聚低耦合&quot;">​</a></h2><ul><li><strong>高内聚</strong>：一个类中的元素紧密相关</li><li><strong>低耦合</strong>：不同类之间的依赖关系尽可能少</li></ul><h2 id="_2-8-组合优于继承" tabindex="-1">2.8 组合优于继承 <a class="header-anchor" href="#_2-8-组合优于继承" aria-label="Permalink to &quot;2.8 组合优于继承&quot;">​</a></h2><p>在许多情况下，使用组合比继承更灵活、更易维护。</p><hr><p>更多内容敬请期待...</p>',19)]))}const P=e(o,[["render",l]]);export{c as __pageData,P as default};
